const antwort = $input.first().json;
const quelle = $("PDF_Text").first().json;

// Feldnamen werden im Browser eventuell übersetzt.
// Hier gelten die ursprünglichen n8n-Namen.
const quelltext = quelle.text;
const rohtext = antwort.text;

function pruefen(ok, meldung) {
  if (!ok) throw new Error(meldung);
}

function hatText(wert) {
  return typeof wert === "string" && wert.trim().length > 0;
}

// Nur Leerzeichen und Zeilenumbrüche vereinheitlichen.
// Wörter und Satzzeichen bleiben unverändert.
function normalisieren(text) {
  return text.normalize("NFC").replace(/\s+/g, " ").trim();
}

pruefen(hatText(quelltext), "Der PDF-Quelltext fehlt.");
pruefen(hatText(rohtext), "Die Gemini-Antwort fehlt.");

let material;
try {
  material = JSON.parse(rohtext);
} catch {
  throw new Error("Gemini hat kein gültiges JSON geliefert.");
}

pruefen(
  material && typeof material === "object"
    && !Array.isArray(material),
  "Die Antwort muss ein JSON-Objekt sein."
);

pruefen(
  hatText(material.zusammenfassung),
  "Die Zusammenfassung fehlt."
);

for (const bereich of ["glossar", "uebungsfragen"]) {
  pruefen(
    Array.isArray(material[bereich])
      && material[bereich].length > 0
      && material[bereich].length <= 3,
    "Erwartet werden 1 bis 3 Einträge: " + bereich
  );
}

function belegPruefen(beleg, stelle) {
  pruefen(
    hatText(beleg)
      && normalisieren(quelltext).includes(normalisieren(beleg)),
    "Quellenbeleg fehlt oder wurde verändert: " + stelle
  );
}

belegPruefen(
  material.zusammenfassungBeleg,
  "Zusammenfassung"
);

material.glossar.forEach((eintrag, index) => {
  pruefen(
    eintrag && hatText(eintrag.begriff)
      && hatText(eintrag.erklaerung),
    "Glossareintrag unvollständig: " + (index + 1)
  );
  belegPruefen(eintrag.beleg, "Glossar " + (index + 1));
});

material.uebungsfragen.forEach((frage, index) => {
  pruefen(
    frage && hatText(frage.frage)
      && hatText(frage.loesung)
      && hatText(frage.erklaerung),
    "Übungsfrage unvollständig: " + (index + 1)
  );
  belegPruefen(frage.beleg, "Übungsfrage " + (index + 1));
});

return [{
  json: {
    modus: "KI-Test mit künstlicher PDF",
    quelle: {
      text: quelltext,
      seitenanzahl: quelle.numpages
    },
    zusammenfassung: material.zusammenfassung,
    zusammenfassungBeleg: material.zusammenfassungBeleg,
    glossar: material.glossar,
    uebungsfragen: material.uebungsfragen,
    technischePruefung: "Bestanden",
    pruefstatus: "Menschliche Prüfung ausstehend"
  }
}];

const item=$input.first();
const text=item.json.text;
if(typeof text!=='string'||!text.trim()) throw new Error('Kein lesbarer PDF-Text. Bitte eine textlesbare PDF verwenden.');
if(text.length>60000) throw new Error('PDF zu lang: maximal 60000 Textzeichen im Web-Test.');
return [item];
